CREATE TABLE public.concorrentes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nome_empresa text NOT NULL UNIQUE, cnpj varchar(14) UNIQUE CHECK (cnpj IS NULL OR cnpj ~ '^[0-9]{14}$'), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.tipos_obra(nome text PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.orgaos_publicos(nome text PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.licitacoes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), edital text NOT NULL, orgao_publico text NOT NULL REFERENCES public.orgaos_publicos(nome) ON UPDATE CASCADE, tipo_obra text NOT NULL REFERENCES public.tipos_obra(nome) ON UPDATE CASCADE, objeto text, valor_estimado numeric(15,2) NOT NULL CHECK (valor_estimado>0), concorrente_vencedor_id uuid NOT NULL REFERENCES public.concorrentes(id) ON DELETE RESTRICT, valor_vencedor numeric(15,2) NOT NULL CHECK (valor_vencedor>0), percentual_desconto numeric(8,4), data_sessao date, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION public.licitacoes_calc() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.percentual_desconto := round(((NEW.valor_estimado-NEW.valor_vencedor)/NEW.valor_estimado)*100,4); NEW.updated_at := now(); RETURN NEW; END $$;
CREATE TRIGGER trg_licitacoes_calc BEFORE INSERT OR UPDATE ON public.licitacoes FOR EACH ROW EXECUTE FUNCTION public.licitacoes_calc();
GRANT SELECT,INSERT,UPDATE,DELETE ON public.concorrentes TO anon, authenticated; GRANT ALL ON public.concorrentes TO service_role; ALTER TABLE public.concorrentes ENABLE ROW LEVEL SECURITY; CREATE POLICY "acesso equipe concorrentes" ON public.concorrentes FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.tipos_obra TO anon, authenticated; GRANT ALL ON public.tipos_obra TO service_role; ALTER TABLE public.tipos_obra ENABLE ROW LEVEL SECURITY; CREATE POLICY "acesso equipe tipos_obra" ON public.tipos_obra FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.orgaos_publicos TO anon, authenticated; GRANT ALL ON public.orgaos_publicos TO service_role; ALTER TABLE public.orgaos_publicos ENABLE ROW LEVEL SECURITY; CREATE POLICY "acesso equipe orgaos_publicos" ON public.orgaos_publicos FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.licitacoes TO anon, authenticated; GRANT ALL ON public.licitacoes TO service_role; ALTER TABLE public.licitacoes ENABLE ROW LEVEL SECURITY; CREATE POLICY "acesso equipe licitacoes" ON public.licitacoes FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);